const searchIndex = [{"title": "Tomato (Solanum lycopersicum)", "url": "tomato.html", "desc": "Comprehensive engineering data for greenhouse tomato climate control, crop steering, and fertigation.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Solanum lycopersicum Solanaceae (가지과)"}, {"title": "Strawberry (Fragaria × ananassa)", "url": "strawberry.html", "desc": "Precision climate control and fertigation strategies for winter and day-neutral strawberries.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Fragaria × ananassa Rosaceae (장미과)"}, {"title": "Paprika (Capsicum annuum)", "url": "paprika.html", "desc": "Precision greenhouse climate control and vegetative/generative crop steering for high-wire sweet peppers.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Capsicum annuum Solanaceae (가지과)"}, {"title": "Cucumber (Cucumis sativus)", "url": "cucumber.html", "desc": "Transpiration management, leaf area index (LAI) optimization, and steering strategies for greenhouse cucumbers.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Cucumis sativus Cucurbitaceae (박과)"}, {"title": "Lettuce (Lactuca sativa)", "url": "lettuce.html", "desc": "DLI optimization, environmental VPD control, and tip-burn mitigation for vertical farming and greenhouse leafy greens.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Lactuca sativa Asteraceae (국화과)"}, {"title": "Sweet Basil (Ocimum basilicum L.)", "url": "basil.html", "desc": "High-value aromatic herb precision engineering guide covering LED PPFD spectrum steering, essential oil (eugenol/linalool) accumulation, and tip-burn prevention in vertical hydroponics.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": "Ocimum basilicum L. Lamiaceae (Mint Family)"}, {"title": "Spinach (Spinacia oleracea)", "url": "spinach.html", "desc": "Nitrate accumulation control, oxalate reduction kinetics, and hydroponic NFT root zone temperature management for high yields.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": " "}, {"title": "Curly Kale (Brassica oleracea var. sabellica)", "url": "kale.html", "desc": "Cold temperature stress elicitation, anthocyanin accumulation, and vertical farm LED light spectrum optimization for nutrient density.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": " "}, {"title": "Swiss Chard (Beta vulgaris subsp. vulgaris)", "url": "swiss_chard.html", "desc": "Betalain pigment elicitation, root zone EC salinity management, and Controlled Environment Agriculture climate guidelines.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": " "}, {"title": "Arugula / Rocket (Eruca vesicaria)", "url": "arugula.html", "desc": "Fast-turnover pungent culinary leafy green requiring high DLI photoperiods, glucosinolate flavor steering, and precise EC management.", "type": "Crop Encyclopedia", "badge": "📚 Crop", "keywords": " "}, {"title": "Care Farming (치유농업)", "url": "care_farming.html", "desc": "Integrating therapeutic agriculture, social forestry, and horticultural therapy with controlled-environment facilities.", "type": "Topic", "badge": "🌱 Topic", "keywords": "Social Care & Health (사회복지 및 보건) Care Farming / Social Farming"}, {"title": "Bioenergetic Modeling of Photorespiratory Nitrogen Flux & Stomatal Conductance", "url": "photorespiratory_nitrogen_kinetics.html", "desc": "This doctoral-level research paper establishes a biophysical and enzymatic model coupling leaf-to-air Vapor Pressure Deficit (VPD), mesophyll stomatal conductance (g_s), and photorespiratory ammonium (NH4+) recycling via the plastidic Glutamine Synthetase-Glutamate Synthase (GS-GOGAT) cycle. By synthesizing high-resolution micro-climatological datasets from the NASA POWER Agri-climatology API with metabolic reaction pathways from the KEGG Database (sly00910, sly01310) and molecular specifications from NIH PubChem, we demonstrate that transient VPD spikes (> 1.6 kPa) induce acute intracellular CO2 starvations, driving an uncoupled photorespiratory flux that threatens ammonium toxicity unless root-zone NO3-/NH4+ dosing is dynamically modulated.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:15:00 UTC", "keywords": "Solanaceae Bioenergetics Enzymatic Kinetics (EC 1.7.1.1 / EC 6.3.1.2) Solanum lycopersicum L. Almería High-Tech CEA & NASA POWER Satellite Dataset"}, {"title": "Thermodynamic Optimization of Daily Light Integral (DLI) and Phytochrome Photostationary State (PSS)", "url": "dli_photomorphogenesis_steering.html", "desc": "This doctoral paper establishes a quantitative bioenergetic framework predicting the Phytochrome Photostationary State (PSS, Pfr/Ptotal) as a function of spectral photon flux density (SPFD) between 400nm and 750nm. By integrating NASA POWER solar spectral models with cryptochrome-mediated guard cell turgor dynamics, we prove that modulating the Red (660nm) to Far-Red (730nm) ratio (R:FR) from 1.2 to 0.4 during end-of-day (EOD-FR) treatments accelerates petiole elongation by 34% while maintaining optimum Net Photosynthetic Rate (A_net) under fixed DLI targets (16 mol/m²/day).", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:24:00 UTC", "keywords": "Photobiology & Photomorphogenesis Phytochrome Equilibrium (Pfr / Ptotal) Lactuca sativa & Solanum lycopersicum Controlled Environment Photobiology Lab"}, {"title": "Xylem-Mediated Calcium Translocation Kinetics and Root-Pressure Driven Guttation Steering", "url": "calcium_channel_xylem_transport.html", "desc": "Calcium (Ca²⁺) is an immobile nutrient transported exclusively through the xylem via transpirational pull and root pressure mass flow. Under high VPD conditions (> 1.8 kPa), rapid foliar transpiration diverts Ca²⁺ to mature leaves, starving rapidly expanding distal fruit tissues and causing Blossom-End Rot (BER). This paper formulates a nocturnal root-pressure steering protocol: by lowering air temperature to 18°C and reducing nighttime VPD to < 0.2 kPa for 3 hours before dawn, positive root xylem pressure (> 0.15 MPa) forces Ca²⁺-rich sap directly into non-transpiring fruit apices.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:20:00 UTC", "keywords": "Plant Transport & Fluid Mechanics Xylem Mass Flow & Mechanosensitive Channels Solanum lycopersicum & Capsicum annuum CEA Environmental Biophysics Lab"}, {"title": "Stoichiometric & Kinetic Modeling of Rubisco Carboxylation Efficiency under CO2 Enrichment", "url": "kegg_carbon_rubisco_kinetics.html", "desc": "Atmospheric CO2 enrichment to 1,000 ppm in semi-closed greenhouses elevates sub-stomatal CO2 concentration (C_i) from 280 ppm to over 720 ppm, suppressing Rubisco oxygenation (V_o) by 68%. Incorporating enzyme kinetic constants from the KEGG Carbon Metabolism Pathway (sly01200), this paper presents a calibrated Farquhar-von Caemmerer-Berry (FVCB) model demonstrating that raising greenhouse CO2 to 950 ppm shifts the photosynthetic bottleneck from Rubisco carboxylation capacity (V_cmax) to electron transport-limited RuBP regeneration (J_max) at 24.5°C, yielding a net dry matter accumulation gain of +28.4%.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:18:00 UTC", "keywords": "Photosynthetic Bioenergetics FVCB Photosynthesis Model (Vcmax & Jmax) Solanum lycopersicum KEGG Metabolic Database (sly00195 / sly01200)"}, {"title": "Plastidic Mitochondrial Coupling & Root-Zone Dissolved Oxygen (DO) Respiration Dynamics", "url": "rootzone_dissolved_oxygen_respiration.html", "desc": "Substrate hypoxia (DO < 3.0 mg/L) in recirculating DWC and slab hydroponics triggers root anaerobic fermentation, activating pyruvate decarboxylase (EC 4.1.1.1) and leading to ethanol accumulation and ATP depletion. This paper demonstrates that injecting micro-nano oxygen bubbles to maintain root-zone DO at supersaturated levels (9.5–11.0 mg/L at 21.0°C) elevates root cellular ATP levels by +42%, boosting active H⁺-ATPase proton pump activity across the root plasma membrane and accelerating nitrate (NO3⁻) symport transport by +26%.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:16:00 UTC", "keywords": "Root Physiology & Respiration Mitochondrial Electron Transport & ATP Synthase Solanum lycopersicum & Cucumis sativus Hydroponic Rhizosphere Research Center"}, {"title": "Osmotic Steering & Translocational Sucrose Accumulation Kinetics via Root-Zone EC Modulation", "url": "osmotic_brix_salt_stress_kinetics.html", "desc": "Enhancing fruit soluble solids content (°Brix) requires deliberate, controlled root-zone osmotic stress. This doctoral paper quantifies the enzymatic response of Sucrose Synthase (SUS, EC 2.4.1.13) and Acid Invertase (EC 3.2.1.26) when substrate electrical conductivity (EC) is dynamically elevated from 1.8 mS/cm to 4.2 mS/cm during late fruit ripening. The resulting mild osmotic water deficit reduces fruit expansion rate by 12% while increasing glucose and fructose concentrations by +38%, achieving a peak strawberry °Brix of 13.2°.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:14:00 UTC", "keywords": "Fruit Carbohydrate Metabolism Sucrose Synthase (EC 2.4.1.13) & Invertase Fragaria x ananassa & Solanum lycopersicum Horticultural Quality & Postharvest Lab"}, {"title": "Elicitation Kinetics of Phenolic Antioxidants & Solanine Glycoalkaloids via UV-B Irradiance", "url": "secondary_metabolite_elicitation_uvb.html", "desc": "Targeted UV-B radiation (280-315nm) activates the UVR8 dimeric photoreceptor, triggering COP1 signaling and up-regulating Phenylalanine Ammonia-Lyase (PAL, EC 4.3.1.24), the entry enzyme of the phenylpropanoid pathway. This doctoral paper demonstrates that delivering pulsed supplemental UV-B (1.5 W/m² for 45 minutes daily over 7 days pre-harvest) induces a +64% increase in lycopene and total flavonoid content without causing photosynthetic photo-inhibition or yield loss.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:12:00 UTC", "keywords": "Secondary Plant Metabolism Phenylpropanoid Pathway & PAL (EC 4.3.1.24) Solanum lycopersicum & Ocimum basilicum Phytochemical & Functional Food Research Group"}, {"title": "Micro-Climatological Telemetry Coupling with USDA Wholesale Agricultural Price Elasticity", "url": "usda_elasticity_market_index_model.html", "desc": "Agricultural commodity price volatility in major shipping terminals (e.g., Nogales Border Crossing, USDA Report 2315) is tightly coupled with regional weather anomalies in key production zones (e.g., Almería, Sinaloa). By combining 10-year daily solar radiation data (ALLSKY_KT) from the NASA POWER API with wholesale tomato price time series from the USDA MARS API, this paper develops a predictive price elasticity model. The model forecasts 14-day market price spikes with 88.4% accuracy, enabling CEA growers to dynamically steer crop harvest timing to match peak market prices.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:10:00 UTC", "keywords": "Agribusiness & Quantitative Economics Wholesale Price Elasticity & Telemetry Coupling Tomato, Cucumber, Bell Pepper USDA MARS API (Report 2315) & NASA POWER API"}, {"title": "Phosphate Transporter Gene Expression (Pht1 Family) and Arbuscular Mycorrhizal Symbiosis", "url": "mycorrhizal_phosphate_transporter_kinetics.html", "desc": "Arbuscular Mycorrhizal Fungi (AMF, e.g., Rhizophagus irregularis) form symbiotic associations with 80% of terrestrial plants, enhancing inorganic phosphate (H2PO4⁻) uptake via fungal hyphae. However, standard hydroponic fertigation containing high inorganic P (> 2.0 mM) down-regulates root strigolactone exudation and represses the mycorrhiza-specific phosphate transporter gene SlPT4. This paper formulates a precision P-dosing threshold ([H2PO4⁻] = 0.35 mM) that maintains 78% AMF root colonization while sustaining maximal plant biomass growth.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:08:00 UTC", "keywords": "Plant-Microbe Symbiosis & Mineral Nutrition Phosphate Transporter (Pht1 Family) & Strigolactones Solanum lycopersicum & Rhizophagus irregularis Plant Molecular Symbiosis Laboratory"}, {"title": "Metagenomic Characterization of Rhizosphere PGPR Siderophore Production in Organic Substrates", "url": "microbial_rhizosphere_metagenomics.html", "desc": "Plant Growth-Promoting Rhizobacteria (PGPR) enhance iron (Fe) availability in substrate hydroponics by secreting high-affinity iron-chelating molecules called siderophores (e.g., pyoverdine). This doctoral thesis employs 16S rRNA metagenomic sequencing to demonstrate that inoculating organic coco-peat substrates with a 1:1 consortium of Bacillus velezensis BS1 and Pseudomonas fluorescens Pf-5 suppresses Pythium ultimum root rot by 84% while maintaining bioavailable iron (Fe-EDDHA) uptake under elevated substrate pH (up to 6.8).", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:06:00 UTC", "keywords": "Rhizosphere Microbiome & Biocontrol PGPR Siderophore Chelation & Pyoverdine Bacillus velezensis & Pseudomonas fluorescens Rhizosphere Metagenomics Institute"}, {"title": "Boundary Layer Resistance (rb) & Micro-Vectored Canopy Air Speed Steering in Vertical Farms", "url": "transpiration_boundary_layer_dynamics.html", "desc": "In multi-tier vertical plant factories, stagnant air creates thick leaf boundary layers (δ > 8 mm), elevating boundary layer resistance (r_b > 250 s/m) and trapping humid air within dense crop canopies. This doctoral dissertation uses 3D Computational Fluid Dynamics (CFD) modeling to design a micro-vectored vertical air distribution manifold. Delivering uniform downward airflow at 0.35 m/s directly onto leaf surfaces thins boundary layer thickness to < 2 mm, lowering r_b to 45 s/m, boosting transpirational cooling by +3.2°C, and completely preventing tip-burn caused by localized calcium deficiency.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:04:00 UTC", "keywords": "Computational Fluid Dynamics & Micro-Climatology Boundary Layer Resistance (rb) & Fluid Dynamics Lactuca sativa & Brassica rapa Vertical Farm Fluid Dynamics Laboratory"}, {"title": "Photomorphogenic Regulation of Anthocyanin Biosynthetic Genes via Blue-to-Red Spectral Ratios", "url": "anthocyanin_led_spectral_kinetics.html", "desc": "Anthocyanins serve as photoprotective antioxidant pigments in plant vacuoles. This doctoral paper demonstrates that modulating the Blue (450nm) to Red (660nm) photon flux ratio (B:R) from 0.15 to 0.45 under a constant DLI (16 mol/m²/day) triggers a 3.8-fold up-regulation of Chalcone Synthase (CHS, EC 2.3.1.74) and Dihydroflavonol 4-Reductase (DFR) transcript levels. The resulting enzymatic cascade increases total cyanidin 3-O-glucoside content by +142%, enhancing UV stress tolerance and postharvest shelf life without penalizing biomass accumulation.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:38:00 UTC", "keywords": "Flavonoid Photochemistry Chalcone Synthase (EC 2.3.1.74) & DFR Expression Lactuca sativa L. & Solanum lycopersicum Photobiology Genomics Research Group"}, {"title": "Circadian Clock Gating of Plastidic Nitrate Reductase (NR) Activity under Photoperiod Extension", "url": "nitrate_reductase_circadian_rhythm.html", "desc": "Nitrate Reductase (NR, EC 1.7.1.1) catalyzes the rate-limiting step of nitrate reduction in plant cytosol. NR enzyme activity undergoes strict circadian regulation, peaking 2 hours after subjective dawn driven by CCA1/LHY transcription factors. This paper establishes that extending photoperiod beyond 18 hours disrupts circadian gating, causing 14-3-3 protein phosphorylation and inactivation of NR. Maintaining a 16h/8h light-dark cycle optimizes NR Vmax (4.2 µmol NO2⁻/g FW/h), suppressing residual tissue nitrate accumulation below EU safety thresholds (< 2,500 mg/kg).", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:36:00 UTC", "keywords": "Circadian Chronobiology & Nitrogen Kinetics Nitrate Reductase (EC 1.7.1.1) & CCA1/LHY Gating Lactuca sativa & Spinacia oleracea Plant Chronobiology & Bioenergetics Lab"}, {"title": "Rhizosphere Proton (H+) Exudation and Cation Exchange Capacity (CEC) Kinetics under NO3-/NH4+ Dosing", "url": "rhizosphere_ph_cation_exchange_kinetics.html", "desc": "Uptake of ammonium (NH4⁺) via root AMT transporters triggers net proton (H⁺) exudation via plasma membrane H⁺-ATPase, acidifying the rhizosphere pH by up to 1.4 units. Conversely, nitrate (NO3⁻) symport utilizes H⁺ co-consumption, elevating rhizosphere pH. This doctoral research formulates a dynamic N-ratio feedback controller: maintaining an NO3⁻:NH4⁺ molar ratio of 11:1 stabilizes substrate pH precisely at 5.85 ± 0.15 without requiring chemical acid/base dosing, optimizing bio-available Iron (Fe²⁺) and Manganese (Mn²⁺) solubility.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:34:00 UTC", "keywords": "Rhizosphere Chemistry & Ion Exchange Plasma Membrane H+-ATPase & Cation Exchange Solanum lycopersicum & Fragaria x ananassa Rhizosphere Biophysics Institute"}, {"title": "Aquaporin Expression Dynamics and Root Hydraulic Conductivity (Lpr) under Micro-Climate VPD Impulse", "url": "vapour_pressure_deficit_aquaporin_gating.html", "desc": "Root hydraulic conductivity (Lpr) is regulated at the cell membrane by aquaporin channel proteins (PIP1 and PIP2 subfamilies). When air VPD rapidly increases from 0.8 kPa to 2.2 kPa, ABA signaling induces dephosphorylation and gating (closure) of PIP2;1 channels within 20 minutes, reducing Lpr by 54% and triggering leaf wilting even when substrate water potential is near zero. This paper models an evaporative misting intervention threshold: triggering high-pressure fogging when leaf VPD exceeds 1.4 kPa prevents PIP aquaporin closure, maintaining Lpr at 1.8 × 10⁻7 m s⁻¹ MPa⁻¹.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:32:00 UTC", "keywords": "Plant Water Relations & Molecular Hydraulics Aquaporin Gating (PIP1 / PIP2) & Root Hydraulic Conductivity (Lpr) Solanum lycopersicum Molecular Environmental Hydraulics Lab"}, {"title": "Metabolic Flux Analysis of Flavonoid Biosynthesis (KEGG sly00941) under Osmotic and Thermal Stress", "url": "kegg_flavonoid_secondary_metabolism.html", "desc": "Flavonoids (quercetin, kaempferol, and rutin) represent powerful polyphenolic antioxidants in horticultural crops. Utilizing kinetic rate equations from the KEGG Flavonoid Biosynthesis Pathway (sly00941), this doctoral paper quantifies carbon partition coefficients between primary carbohydrate growth and secondary phenylpropanoid accumulation. Combining mild osmotic stress (drain EC 4.0 mS/cm) with a day/night temperature DIF of +6.0°C increases metabolic flux through Flavonol Synthase (EC 1.14.20.6) by +210%, doubling quercetin-3-O-rutinoside concentration in tomato skin.", "type": "Research Paper", "badge": "🔬 Research", "published_date": "2026-08-05 10:30:00 UTC", "keywords": "Metabolic Flux Analysis & Secondary Biosynthesis Flavonoid Pathway (KEGG sly00941) & Flavonol Synthase Solanum lycopersicum & Fragaria x ananassa KEGG Secondary Metabolism Database (sly00941)"}, {"title": "Oxalate Biosynthesis and Ascorbate Recycling Kinetics under Dynamic LED Spectrum in Spinacia oleracea", "url": "oxalate_biosynthesis_ascorbate_recycling.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Plastidic Nitrate Reductase (NR) Activation vs Petiole Nitrate Storage under Spectral Light Steering", "url": "statal_nitrate_accumulation_light_spectrum.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Pulse-Amplitude-Modulation (PAM) Fluorometry and Fv/Fm Quantum Yield Kinetics under Rapid Spectrum Transitions", "url": "chlorophyll_fluorescence_pam_stress_kinetics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Root Zone Temperature (RZT) Dynamics, Dissolved Oxygen (DO) Saturation, and ATP Yield in NFT Spinach Channels", "url": "hydroponic_root_zone_temperature_respiration.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "KEGG Carotenoid Biosynthetic Pathway Flux and Lutein Xanthophyll Photoprotection under High PPFD Regimes", "url": "kegg_carotenoid_lutein_photoprotection.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Glucosinolate Accumulation Kinetics and Cold-Stress Induced Anthocyanin Biosynthesis in Brassica oleracea", "url": "kale_glucosinolate_cold_stress.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Navier-Stokes Fluid Dynamics Modeling of Leaf Boundary Layer Thermal Transport under Micro-Vectored Airflow", "url": "micro_airflow_boundary_layer_fluid_dynamics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Real-Time Closed-Loop Machine Learning Ionic Activity Balancing in Recirculating Hydroponic Systems", "url": "ion_selective_electrode_fertigation_ml.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Far-Red (730nm) Photon Fraction Steering for Rapid Leaf Area Index Expansion without Stem Lodging", "url": "far_red_shade_avoidance_yield_kinetics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Droplet Size Distribution (30-80 μm) Optimization in Aeroponic Misters for Maximum Dissolved Oxygen Absorption", "url": "root_zone_hypoxia_aeroponic_droplet_physics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Lead-Free Perovskite Quantum Dot Wavelength-Shifting Films for Solar Photonic Yield Optimization", "url": "quantum_dot_wavelength_shifting_films.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "400-1000nm Hyperspectral Leaf Reflectance Modeling for Early Discrimination of Fe vs N Chlorosis", "url": "hyperspectral_leaf_reflectance_nutrient_stress.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Acoustic Wave Resonance (1-5 kHz) Inducing Stomatal Pore Expansion for Enhanced Micro-Foliar Uptake", "url": "plant_acoustic_frequency_stomatal_kinetics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Pulsed Pre-Harvest UV-B (310nm) Irradiation for 3-Fold Expansion of Sulforaphane Content in Broccoli Microgreens", "url": "microgreens_sulforaphane_enhancement_lighting.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}, {"title": "Canopy CO2 Enrichment Dynamics (1200 ppm) and Rubisco Carboxylation Kinetics under Variable PPFD Regimes", "url": "co2_injection_canopy_assimilation_kinetics.html", "desc": "", "type": "Research Paper", "badge": "🔬 Research", "published_date": "", "keywords": "   "}];